var ch = Channel.CreateBounded<Job>(100);

async Task ProduceAsync()
{
    try
    {
        foreach (var job in jobs)
            await ch.Writer.WriteAsync(job);   // 100 в очереди — ждём без потока
    }
    finally { ch.Writer.Complete(); }          // без этого потребители ждут вечно
}

async Task ConsumeAsync()
{
    await foreach (var job in ch.Reader.ReadAllAsync())   // каждый job — одному
        await HandleAsync(job);                           // выход: закрыт и пуст
}

var consumers = Enumerable.Range(0, 4).Select(_ => ConsumeAsync()).ToArray();
await Task.WhenAll(consumers.Append(ProduceAsync()));

