var gate = new SemaphoreSlim(8);   // 8 мест
var pages = await Task.WhenAll(urls.Select(async url =>
{
    await gate.WaitAsync();        // 9-я и дальше ждут здесь, без потоков
    try     { return await DownloadAsync(url); }
    finally { gate.Release(); }    // место — следующему
}).ToArray());
